/**
 * @method
 * @name ipt_addIsuShrs_onclick
 * @description 「추가발행수량」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_addIsuShrs_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05027.ipt_addIsuShrs_onclick' }); }
};

/**
 * @method
 * @name ipt_addIsuShrs_onkeyup
