 * @returns {void}
 * @hidden N
 */
scwin.ipt_addIsuShrs_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05027.ipt_addIsuShrs_onkeyup' }); }
};

/**
