 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_addIsuShrs_onblur = async function(e){
    try {
        await scwin.calcIsuTotSumAdd('' + dma_readDataVO.get("listProcsStatCd") + '');scwin.calcSumFinancing()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05027.ipt_addIsuShrs_onblur' }); }
};

