///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_loadListReq",
        target: "dlt_codeLeadcom=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openInstCodeWin
 * @description open Inst Code Win 처리
 * @param {*} objName1 objName1
 * @param {*} objName2 objName2
 * @returns {void}
 * @hidden N
 */
scwin.openInstCodeWin = function (objName1, objName2) {
    if (scwin.instCodeWin != null) {
        if (!scwin.instCodeWin.closed) {
            scwin.instCodeWin.close();
        }
    }
    scwin.openCodeObj = objName1;
    scwin.openNameObj = objName2;
