/**
 * @method
 * @name setListCommission
 * @description set List Commission 처리
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.setListCommission = function (value) {
    let v1 = 0;
    let v2 = 0;
    if (value >= 1000000000 && value < 2000000000) {
        v1 = value - 1000000000;
        v2 = 300000 + (v1 * 0.025 / 100);
    } else {
        if (value >= 2000000000 && value < 5000000000) {
            v1 = value - 2000000000;
            v2 = 550000 + (v1 * 0.0183 / 100);
        } else {
            if (value >= 5000000000 && value < 10000000000) {
                v1 = value - 5000000000;
                v2 = 1100000 + (v1 * 0.016 / 100);
            } else {
                if (value >= 10000000000 && value < 50000000000) {
                    v1 = value - 10000000000;
                    v2 = 1900000 + (v1 * 0.015 / 100);
                } else {
                    if (value >= 50000000000 && value < 100000000000) {
                        v1 = value - 50000000000;
                        v2 = 7900000 + (v1 * 0.004 / 100);
                    } else {
                        if (value >= 100000000000 && value < 500000000000) {
                            v1 = value - 100000000000;
                            v2 = 9900000 + (v1 * 0.003 / 100);
                        } else {
                            if (value >= 500000000000 && value < 1000000000000) {
                                v1 = value - 500000000000;
                                v2 = 21900000 + (v1 * 0.002 / 100);
                            } else {
                                if (value >= 1000000000000) {
                                    v1 = value - 1000000000000;
                                    v2 = 31900000 + (v1 * 0.001 / 100);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    return $c.num.formatNumber(scwin.cuttingNumber(parseInt(v2)));
};

