/**
 * @method
 * @name cuttingNumber
 * @description cutting Number 처리
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.cuttingNumber = function (value) {
    const str = "" + value;
    let v1 = 0;
    if (str.length > 3) {
        str2 = str.substring(0, str.length - 2);
        v1 = parseInt(str2 + "00");
    }
    return v1;
};

