            await $c.win.alert("신청인정보  페이지까지 입력을 하셔야만 제출 하실수 있습니다.");
            return ;
        }

        //-- 기준가격,행사가격 데이타 검증 -->
        if(!fn_chkSaveElwPrc() ) return  ;

        $c.util.getComponent('dma_RegisterReq').set('listProcsStatCd', CD_STAT_FIN) ;  /* 상장처리상태코드 */

        if (! await scwin.confirmJob('S') )  return ;

        scwin.form.action = '/list/elwPage.do';
        $c.util.getComponent('dma_RegisterReq').set('method', 'elwPageSub');
        await moveUrl('/list/elwPage.do', {});
    }

};

/**
 * @method
 * @name isPossibleSave
 * @description is Possible Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isPossibleSave = async function () {
    isNotAdmin();

    // BZ_ADDPRE 중  '00' , '02' 만 저장가능
    // 2012/08/08 KBoY 반송시 해당탭으로 이동하기 위해 반송시 기존꺼 02로 돌리고 03으로 하나를 카피 뜨기 때문에 02로 올 일이 없다.
    if( $c.util.getComponent("dma_RegisterReq").get("bzCd") === scwin.BZ_ADDPRE || $c.util.getComponent("dma_RegisterReq").get("bzCd") === scwin.BZ_ADDLST) {
        if( $c.util.getComponent('dma_RegisterReq').get('listProcsStatCd') !== "" && $c.util.getComponent('dma_RegisterReq').get('listProcsStatCd') !== CD_STAT_ING && $c.util.getComponent('dma_RegisterReq').get('listProcsStatCd') !== '03' ) {

            await $c.win.alert("\n 해당 종목이 처리중입니다.       \n\n 목록에서 상태를 확인하세요.") ;
            return  false;
        }
    }

    // 반송된 업무처리일경우는 첫페이지에서만 저장이 가능 2012-07-31 KBoY 03으로 오기 때문에 앞으로 여기 올일 없음.
    if( $c.util.getComponent('dma_RegisterReq').get('listProcsStatCd') === CD_STAT_REJ ) {

        if(($c.util.getComponent("dma_RegisterReq").get("nowPage")) === 1 ) {

            $c.util.getComponent("dma_RegisterReq").set("bzProcsNo", "");
            $c.util.getComponent("dma_RegisterReq").set("transKind", INSERT);
            $c.util.getComponent('dma_RegisterReq').set('listProcsStatCd', CD_STAT_ING) ;  /* 상장처리상태코드 */

            return true ;

        } else {
            await $c.win.alert("\n 현재 텝에서는 저장을 할수 없습니다. \n\n 증권발행개요 탭으로 이동후, 저장을 하세요") ;
            return false ;
        }
    }

    // 3단계(파일첨부) 입력안해도 다음단계로 이동가능하도록 수정 (2010-02-01)
    if($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd") < 2) {
        if( ($c.util.getComponent("dma_RegisterReq").get("nowPage")) > (($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd")) + 1)) {
            await $c.win.alert("\n 현재 텝에서는 저장을 할수 없습니다. \n\n 탭별로 작성후 저장하셔야 합니다..");
            return false ;
        }
    }
    // 2012-07-31 KBoY 다시 저장할때 prelistBizImpl doChangeListPorcsStatCd()에서 '03'받아다 00으로 강제 세팅함...
    if( $c.util.getComponent('dma_RegisterReq').get('listProcsStatCd') !== '03' ) {
        $c.util.getComponent('dma_RegisterReq').set('listProcsStatCd', CD_STAT_ING) ;  /* 상장처리상태코드 */
    }

    // viewFormNameAndData();
    if( $c.util.getComponent("dma_RegisterReq").get("bzProcsNo") === "" )
    $c.util.getComponent("dma_RegisterReq").set("transKind", INSERT);
    else
    $c.util.getComponent("dma_RegisterReq").set("transKind", UPDATE);

    return true ;

};

/**
 * @method
 * @name setElwKoValuPrcMethd
 * @description set Elw Ko Valu Prc Methd 처리
 * @returns {void}
 * @hidden N
 */
scwin.setElwKoValuPrcMethd = function () {
    $c.util.getComponent('ipt_elwKoValuPrcMethd').setStyle("background", '#D9D9D9');
    $c.util.getComponent('ipt_elwKoValuPrcMethd').readOnly = true;
    $c.util.getComponent('ipt_elwKoValuPrcMethd').setValue("");

    if ($c.util.getComponent('slc_elwRghtTpKindCd').getValue()=== "3") { // 조기종료형
        if ($c.util.getComponent('slc_elwRghtTpCd').getValue()=== "C") { // 콜
            $c.util.getComponent('ipt_elwKoValuPrcMethd').setValue("12시전 조기종료이벤트 발생시 조기종료발생시점이후부터 당일 장종료시점까지의 기초자산 체결가격 중 가장 낮은 가격 이상, 12시이후 조기종료이벤트 발생시 조기종료발생시점이후부터 익일 12시전까지의 기초자산 체결가격 중 가장 낮은 가격 이상");
        } else if ($c.util.getComponent('slc_elwRghtTpCd').getValue()=== "P") { // 풋

            $c.util.getComponent('ipt_elwKoValuPrcMethd').setValue("12시전 조기종료이벤트 발생시 조기종료발생시점이후부터 당일 장종료시점까지의 기초자산 체결가격 중 가장 높은 가격 이하, 12시이후 조기종료이벤트 발생시 조기종료발생시점이후부터 익일 12시전까지의 기초자산 체결가격 중 가장 높은 가격 이하");
        }
    } /* 2010.08.25 삭제요청
    else { // 표준형,디지털형
        $c.util.getComponent('ipt_elwKoValuPrcMethd').setValue("해당사항 없음");
    } */

};

/**
 * @method
 * @name confirmJob
 * @description 업무 처리 확인 — "[저장] 하시겠습니까?" 확인창(as-is 공통 fn_isProcess 의 의미 보존 · pcc/fil 반입 후보)
 * @param {*} gubun 처리 구분(I 저장 · U 수정 · D 삭제 · S 제출 · R 해제 · DSCL 안내문작성)
 * @returns {Promise<Boolean>} 확인이면 true
 * @hidden N
 */
scwin.confirmJob = async function (gubun) {
    const job = { I: "저장", U: "수정", D: "삭제", S: "제출", R: "해제", DSCL: "안내문작성" }[gubun] || gubun;
    return $c.win.confirm("[" + job + "] 하시겠습니까?");
};
